import { useMutation } from '@tanstack/react-query';
import axios from 'axios';
import { CstmrUpdateParams } from '~/entities/user/model/types';
import { CBDCAxiosError } from '~/shared/@types/error';
import { MutationOptions } from '~/shared/@types/query';
import { API_URLS } from '~/shared/api/api-urls';
import { resultify } from '~/shared/lib/utils/resultify';

const updateCstmr = (tbCstmrMastr: CstmrUpdateParams) => {
  // const id = tbCstmrMastr?.cstmrNo ?? '';
  // if (!id) {
  //   throw new Error(i18n.t('validation:temporaryErrorOccurred'));
  // }
  return resultify(axios.post<any>(API_URLS.cstmr(`put/update`), { tbCstmrMastr }));
};

export const useUpdateCstmrMutation = (
  options?: MutationOptions<CstmrUpdateParams, CBDCAxiosError, CstmrUpdateParams>,
) => {
  const mutation = useMutation<CstmrUpdateParams, CBDCAxiosError, CstmrUpdateParams>({
    ...options,
    mutationFn: (tbCstmrMastr: CstmrUpdateParams) => updateCstmr(tbCstmrMastr),
  });

  return {
    ...mutation,
  };
};
