import { useStore } from '~/app/store/store';
import { setUserRes, useGetUserInfoQuery } from '~/entities/user/api/use-get-cstmr-query';
import { useUpdateCstmrMutation } from '~/entities/user/api/use-update-cstmr-mutation';
import { CstmrUpdateParams } from '~/entities/user/model/types';

export const useUpdateUserInfo = () => {
  const { mutateAsync: updateCstmr } = useUpdateCstmrMutation();
  const { data: userRes } = useGetUserInfoQuery();

  const updateUserInfo = async (update: CstmrUpdateParams | ((prev: CstmrUpdateParams) => CstmrUpdateParams)) => {
    const token = useStore.getState().authSlice.jwt;
    if (!token) {
      console.error('JWT Token is not found');
      return;
    }

    if (!userRes?.tbCstmrMastr?.cstmrNo) {
      console.error('Customer number is not found');
      return;
    }

    const updatedInfo = typeof update === 'function' ? update(userRes?.tbCstmrMastr) : update;
    const params: CstmrUpdateParams = {
      cstmrNo: userRes?.tbCstmrMastr?.cstmrNo ?? '',
      ...updatedInfo,
    };

    await updateCstmr(params);
    setUserRes((prev) => ({
      ...prev,
      tbCstmrMastr: {
        ...prev.tbCstmrMastr,
        ...params,
      },
    }));
  };

  return {
    updateUserInfo,
  };
};
